function blocking(violations) {
  return violations
    .filter(v => v.impact === 'serious' || v.impact === 'critical')
    .map(v => v.id)
    .sort();
}

function newViolations(current, baseline) {
  const known = new Set(baseline.map(v => v.ruleId + '|' + v.target));
  const out = [];
  for (const v of current) {
    const key = v.ruleId + '|' + v.target;
    if (!known.has(key) && !out.includes(key)) out.push(key);
  }
  return out;
}

