def _lum(hex_):
    hex_ = hex_.lstrip('#')
    vals = []
    for i in (0, 2, 4):
        s = int(hex_[i:i + 2], 16) / 255
        vals.append(s / 12.92 if s <= 0.04045 else ((s + 0.055) / 1.055) ** 2.4)
    r, g, b = vals
    return 0.2126 * r + 0.7152 * g + 0.0722 * b

def contrast(hex1, hex2):
    a, b = _lum(hex1), _lum(hex2)
    hi, lo = max(a, b), min(a, b)
    return round((hi + 0.05) / (lo + 0.05), 2)

def passes_aa(hex1, hex2, large=False):
    return contrast(hex1, hex2) >= (3.0 if large else 4.5)
